-- 0019_logistics_returns.sql
create schema if not exists logistics;
create table if not exists logistics.carriers(id uuid primary key default gen_random_uuid(),code text unique not null,name text not null,is_active boolean not null default true,created_at timestamptz not null default now());
create table if not exists logistics.shipments(id uuid primary key default gen_random_uuid(),order_id uuid not null references commerce.orders(id),carrier_id uuid references logistics.carriers(id),tracking_number text,status text not null default 'pending' check(status in ('pending','created','picked_up','in_transit','out_for_delivery','delivered','failed','returned','cancelled')),shipped_at timestamptz,delivered_at timestamptz,metadata jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create unique index if not exists logistics_shipments_tracking_uq on logistics.shipments(tracking_number) where tracking_number is not null;
create table if not exists logistics.tracking_events(id uuid primary key default gen_random_uuid(),shipment_id uuid not null references logistics.shipments(id) on delete cascade,status text not null,event_code text,description text,location_text text,occurred_at timestamptz not null default now(),raw_payload jsonb not null default '{}',created_at timestamptz not null default now());
create table if not exists logistics.returns(id uuid primary key default gen_random_uuid(),order_id uuid not null references commerce.orders(id),customer_id uuid not null references customer.customers(id),status text not null default 'requested' check(status in ('requested','approved','rejected','received','inspected','refunded','cancelled')),reason text,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists logistics.return_items(id uuid primary key default gen_random_uuid(),return_id uuid not null references logistics.returns(id) on delete cascade,order_item_id uuid not null references commerce.order_items(id),quantity numeric not null check(quantity>0),disposition text check(disposition in ('restock','damaged','quarantine','reject')),notes text,created_at timestamptz not null default now());
alter table logistics.carriers enable row level security;
alter table logistics.shipments enable row level security;
alter table logistics.tracking_events enable row level security;
alter table logistics.returns enable row level security;
alter table logistics.return_items enable row level security;
drop policy if exists carriers_staff_read on logistics.carriers; create policy carriers_staff_read on logistics.carriers for select to authenticated using (platform.has_permission(auth.uid(),'shipping.read') or platform.has_permission(auth.uid(),'shipping.manage'));
drop policy if exists shipments_staff_manage on logistics.shipments; create policy shipments_staff_manage on logistics.shipments for all to authenticated using (platform.has_permission(auth.uid(),'shipping.manage')) with check (platform.has_permission(auth.uid(),'shipping.manage'));
drop policy if exists shipments_customer_read on logistics.shipments; create policy shipments_customer_read on logistics.shipments for select to authenticated using (exists(select 1 from commerce.orders o join customer.customers c on c.id=o.customer_id where o.id=shipments.order_id and c.auth_user_id=auth.uid()));
drop policy if exists tracking_staff_read on logistics.tracking_events; create policy tracking_staff_read on logistics.tracking_events for select to authenticated using (platform.has_permission(auth.uid(),'shipping.read') or exists(select 1 from logistics.shipments s join commerce.orders o on o.id=s.order_id join customer.customers c on c.id=o.customer_id where s.id=tracking_events.shipment_id and c.auth_user_id=auth.uid()));
drop policy if exists tracking_staff_manage on logistics.tracking_events; create policy tracking_staff_manage on logistics.tracking_events for insert to authenticated with check (platform.has_permission(auth.uid(),'shipping.manage'));
drop policy if exists returns_customer_read on logistics.returns; create policy returns_customer_read on logistics.returns for select to authenticated using (customer_id=(select c.id from customer.customers c where c.auth_user_id=auth.uid()) or platform.has_permission(auth.uid(),'orders.manage'));
drop policy if exists returns_customer_create on logistics.returns; create policy returns_customer_create on logistics.returns for insert to authenticated with check (customer_id=(select c.id from customer.customers c where c.auth_user_id=auth.uid()));
drop policy if exists returns_staff_manage on logistics.returns; create policy returns_staff_manage on logistics.returns for update to authenticated using (platform.has_permission(auth.uid(),'orders.manage')) with check (platform.has_permission(auth.uid(),'orders.manage'));
drop policy if exists return_items_read on logistics.return_items; create policy return_items_read on logistics.return_items for select to authenticated using (exists(select 1 from logistics.returns r where r.id=return_items.return_id and (r.customer_id=(select c.id from customer.customers c where c.auth_user_id=auth.uid()) or platform.has_permission(auth.uid(),'orders.manage'))));
drop policy if exists return_items_create on logistics.return_items; create policy return_items_create on logistics.return_items for insert to authenticated with check (exists(select 1 from logistics.returns r where r.id=return_items.return_id and r.customer_id=(select c.id from customer.customers c where c.auth_user_id=auth.uid())) or platform.has_permission(auth.uid(),'orders.manage'));
create or replace function logistics.create_shipment(p_order_id uuid,p_carrier_id uuid default null,p_tracking_number text default null) returns logistics.shipments language plpgsql security definer set search_path=logistics,commerce,platform,public as $$ declare v logistics.shipments;o commerce.orders;begin if auth.uid() is null or not platform.has_permission(auth.uid(),'shipping.manage') then raise exception 'FORBIDDEN';end if;select * into o from commerce.orders where id=p_order_id for update;if not found then raise exception 'ORDER_NOT_FOUND';end if;if o.status not in ('processing','shipped') then raise exception 'INVALID_ORDER_FOR_SHIPMENT';end if;insert into logistics.shipments(order_id,carrier_id,tracking_number,status,shipped_at) values(p_order_id,p_carrier_id,nullif(trim(p_tracking_number),''),'created',now()) returning * into v;if o.status='processing' then perform commerce.transition_order(p_order_id,'shipped','shipment_created');end if;return v;end;$$;
revoke all on function logistics.create_shipment(uuid,uuid,text) from public;grant execute on function logistics.create_shipment(uuid,uuid,text) to authenticated;
create or replace function logistics.record_tracking_event(p_shipment_id uuid,p_status text,p_event_code text default null,p_description text default null,p_location text default null,p_occurred_at timestamptz default null,p_raw_payload jsonb default '{}') returns logistics.tracking_events language plpgsql security definer set search_path=logistics,commerce,platform,public as $$ declare e logistics.tracking_events;s logistics.shipments;begin if auth.uid() is null or not platform.has_permission(auth.uid(),'shipping.manage') then raise exception 'FORBIDDEN';end if;select * into s from logistics.shipments where id=p_shipment_id for update;if not found then raise exception 'SHIPMENT_NOT_FOUND';end if;if p_status not in ('pending','created','picked_up','in_transit','out_for_delivery','delivered','failed','returned','cancelled') then raise exception 'INVALID_SHIPMENT_STATUS';end if;insert into logistics.tracking_events(shipment_id,status,event_code,description,location_text,occurred_at,raw_payload) values(p_shipment_id,p_status,p_event_code,p_description,p_location,coalesce(p_occurred_at,now()),coalesce(p_raw_payload,'{}')) returning * into e;update logistics.shipments set status=p_status,delivered_at=case when p_status='delivered' then now() else delivered_at end,updated_at=now() where id=p_shipment_id;if p_status='delivered' then perform commerce.transition_order(s.order_id,'delivered','shipment_delivered');end if;return e;end;$$;
revoke all on function logistics.record_tracking_event(uuid,text,text,text,text,timestamptz,jsonb) from public;grant execute on function logistics.record_tracking_event(uuid,text,text,text,text,timestamptz,jsonb) to authenticated;
create or replace function logistics.request_return(p_order_id uuid,p_reason text,p_notes text default null) returns logistics.returns language plpgsql security definer set search_path=logistics,commerce,customer,public as $$ declare o commerce.orders;c customer.customers;r logistics.returns;begin if auth.uid() is null then raise exception 'UNAUTHENTICATED';end if;select * into c from customer.customers where auth_user_id=auth.uid();select * into o from commerce.orders where id=p_order_id;if not found then raise exception 'ORDER_NOT_FOUND';end if;if o.customer_id<>c.id then raise exception 'FORBIDDEN';end if;if o.status<>'delivered' then raise exception 'RETURN_NOT_ELIGIBLE';end if;if exists(select 1 from logistics.returns where order_id=p_order_id and status not in ('rejected','cancelled')) then raise exception 'RETURN_ALREADY_EXISTS';end if;insert into logistics.returns(order_id,customer_id,status,reason,notes) values(p_order_id,c.id,'requested',p_reason,p_notes) returning * into r;return r;end;$$;
revoke all on function logistics.request_return(uuid,text,text) from public;grant execute on function logistics.request_return(uuid,text,text) to authenticated;
create or replace function logistics.transition_return(p_return_id uuid,p_to_status text,p_reason text default null) returns logistics.returns language plpgsql security definer set search_path=logistics,platform,public as $$ declare r logistics.returns;f text;begin if auth.uid() is null or not platform.has_permission(auth.uid(),'orders.manage') then raise exception 'FORBIDDEN';end if;select * into r from logistics.returns where id=p_return_id for update;if not found then raise exception 'RETURN_NOT_FOUND';end if;f:=r.status;if not ((f='requested' and p_to_status in ('approved','rejected','cancelled')) or (f='approved' and p_to_status in ('received','cancelled')) or (f='received' and p_to_status in ('inspected','cancelled')) or (f='inspected' and p_to_status in ('refunded','cancelled'))) then raise exception 'INVALID_RETURN_TRANSITION:%:%',f,p_to_status;end if;update logistics.returns set status=p_to_status,updated_at=now(),notes=coalesce(p_reason,notes) where id=p_return_id returning * into r;return r;end;$$;
revoke all on function logistics.transition_return(uuid,text,text) from public;grant execute on function logistics.transition_return(uuid,text,text) to authenticated;
create unique index if not exists finance_payments_provider_ref_uq on finance.payments(provider_code,provider_reference) where provider_reference is not null;